{
  "steps": [
    {
      "step_id": 1,
      "time": "07:30",
      "role": "市气象局",
      "action": "灾害预警",
      "description": "气象部门监测到持续强降雨天气过程，发布地质灾害气象风险预警信息（橙色/红色级别），通过突发事件预警信息发布平台向资源规划、应急管理等部门及社会公众发布，提示相关区域加强巡查排查，做好受威胁群众转移准备。依据《厦门市地质灾害应急预案》预警分级与防御措施要求执行。",
      "resources": [
        { "resource_type": "气象监测设备", "quantity": 3 }
      ]
    },
    {
      "step_id": 2,
      "time": "07:40",
      "role": "市资源规划局",
      "action": "灾害预警",
      "description": "市资源规划局根据气象预警信息与地质灾害隐患点监测数据，联合市气象局发布地质灾害气象风险预警，通知各区、镇（街）、村（居）及群测群防员加密对地质灾害隐患点的监测巡查，发现险情立即上报。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 5 },
        { "resource_type": "卫星电话", "quantity": 3 }
      ]
    },
    {
      "step_id": 3,
      "time": "07:50",
      "role": "社区/基层",
      "action": "险情巡查",
      "description": "村干部、监测员及群测群防员按照预警要求，对山区地质灾害隐患点开展加密巡查排查，重点监测滑坡体裂缝变化、地表位移、地下水异常等情况，发现险情迹象立即向镇政府及自然资源部门报告。",
      "resources": [
        { "resource_type": "监测仪器", "quantity": 2 },
        { "resource_type": "对讲机", "quantity": 5 }
      ]
    },
    {
      "step_id": 4,
      "time": "08:00",
      "role": "社区/基层",
      "action": "灾情上报",
      "description": "监测员在巡查中发现滑坡隐患点出现明显变形加剧迹象，立即向镇政府报告险情信息，同时越级向区应急局、市应急局和市资源规划局报告。报告内容包括地质灾害发生时间、地点、类型、灾害体规模、可能的引发因素、发展趋势及先期处置情况等，符合速报要求。",
      "resources": [
        { "resource_type": "卫星电话", "quantity": 1 },
        { "resource_type": "对讲机", "quantity": 2 }
      ]
    },
    {
      "step_id": 5,
      "time": "08:05",
      "role": "市资源规划局",
      "action": "会商研判",
      "description": "市应急局和市资源规划局接到地质灾害报告后，相互通报信息并组织会商研判，核实灾情险情，分析灾害发展趋势，按相关规定向省自然资源厅、省应急厅、市委市政府报告，同时对灾情进行核实并及时续报。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 2 },
        { "resource_type": "无人机", "quantity": 1 }
      ]
    },
    {
      "step_id": 6,
      "time": "08:15",
      "role": "应急指挥部",
      "action": "启动响应",
      "description": "西安市（厦门市）立即启动《突发地质灾害应急预案》Ⅱ级响应，成立市突发地质灾害应急指挥部和现场指挥部，命令市防灾减灾救灾工作委员会各成员单位按照预案职责指导属地开展人员疏散安置、应急救援、交通疏导、警戒防控等工作。指挥部下设综合协调组、抢险救援组、医疗救护组、交通管制组、疏散引导组、后勤保障和善后安置组、调查评估组、气象/监测组等工作组。",
      "resources": [
        { "resource_type": "指挥车", "quantity": 1 },
        { "resource_type": "卫星电话", "quantity": 2 }
      ]
    },
    {
      "step_id": 7,
      "time": "08:20",
      "role": "应急指挥部",
      "action": "信息通报",
      "description": "应急指挥部向各成员单位通报地质灾害险情信息及启动Ⅱ级响应的决定，要求各部门按职责分工迅速行动。同时按规定向省自然资源厅、省应急厅、市委市政府报告灾情信息，并做好续报和终报工作。",
      "resources": [
        { "resource_type": "通信设备", "quantity": 3 }
      ]
    },
    {
      "step_id": 8,
      "time": "08:25",
      "role": "交通管制组",
      "action": "交通管制",
      "description": "警戒防控组（交通管制组）对受灾区域的道路入口实施临时交通管制措施，严禁无关车辆及人员进入危险区域，设置警示标志，封锁进出道路，保障救援通道畅通。",
      "resources": [
        { "resource_type": "警车", "quantity": 3 },
        { "resource_type": "警示标志", "quantity": 10 }
      ]
    },
    {
      "step_id": 9,
      "time": "08:25",
      "role": "区政府",
      "action": "危险区划定",
      "description": "属地政府及有关部门、镇（街）和村（居）立即派人赶赴现场开展调查，根据滑坡体规模及影响范围划定危险区，设立警示标志，封锁进出道路，禁止无关人员进入。",
      "resources": [
        { "resource_type": "警示标志", "quantity": 20 },
        { "resource_type": "警戒带", "quantity": 500 }
      ]
    },
    {
      "step_id": 10,
      "time": "08:30",
      "role": "社区/基层",
      "action": "人员转移引导",
      "description": "村干部、监测员带领志愿者，通过敲锣发出撤离信号和广播通知受威胁群众，按照预定的安全撤离路线，引导大家有序转移到安全区域。在转移过程中，特别安排专人照顾老弱病残孕等特殊人群，确保每个人的安全。",
      "resources": [
        { "resource_type": "铜锣", "quantity": 3 },
        { "resource_type": "扩音器", "quantity": 2 },
        { "resource_type": "运输车辆", "quantity": 3 }
      ]
    },
    {
      "step_id": 11,
      "time": "08:35",
      "role": "市资源规划局",
      "action": "危险区排查",
      "description": "市资源规划局、市住房局、市建设局会同社区/基层对地质灾害危险区开展全面排查，利用专业监测设备对滑坡体及周边区域进行详细勘查，查明灾害体规模、影响范围及发展趋势，为人员转移和应急救援提供技术支撑。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 3 },
        { "resource_type": "无人机", "quantity": 2 }
      ]
    },
    {
      "step_id": 12,
      "time": "08:40",
      "role": "气象/监测组",
      "action": "险情监测",
      "description": "调查监测组（气象/监测组）制定监测方案，明确监测方法，调集专业监测设备对滑坡体及周边区域实施实时严密监测，密切关注雨情、水情变化和滑坡体位移情况，对灾情发展趋势进行预测及监测，及时发布监测预警信息。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 5 },
        { "resource_type": "气象监测设备", "quantity": 2 },
        { "resource_type": "无人机", "quantity": 1 }
      ]
    },
    {
      "step_id": 13,
      "time": "08:45",
      "role": "应急指挥部",
      "action": "应急队伍集结",
      "description": "应急指挥部命令市消防救援支队、抢险救援组、厦门警备区、武警厦门支队、中国安能二局厦门分公司等应急队伍迅速集结，携带破拆工具、生命探测仪、挖掘机、吊装设备等装备赶赴现场，做好应急救援准备。",
      "resources": [
        { "resource_type": "消防车", "quantity": 3 },
        { "resource_type": "挖掘机", "quantity": 2 },
        { "resource_type": "生命探测仪", "quantity": 2 },
        { "resource_type": "破拆工具", "quantity": 5 }
      ]
    },
    {
      "step_id": 14,
      "time": "08:50",
      "role": "交通管制组",
      "action": "救援引导",
      "description": "交通管制组在通往灾区的主要路口安排人员引导救援车辆和队伍快速通行，确保救援通道畅通无阻，同时维持现场交通秩序。",
      "resources": [
        { "resource_type": "警车", "quantity": 2 },
        { "resource_type": "对讲机", "quantity": 5 }
      ]
    },
    {
      "step_id": 15,
      "time": "08:50",
      "role": "现场指挥部",
      "action": "安全确认",
      "description": "现场指挥部组织市资源规划局、调查评估组及工程抢险组专家对滑坡体及周边区域进行安全评估，确认救援作业区域无次生灾害风险后，方可组织救援人员进入现场开展搜救作业。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 2 },
        { "resource_type": "无人机", "quantity": 1 }
      ]
    },
    {
      "step_id": 16,
      "time": "08:55",
      "role": "消防救援组",
      "action": "救援搜救",
      "description": "在疏散群众撤离过程中突发滑坡灾害，导致5人失联。市消防救援支队、抢险救援组携带生命探测仪、破拆工具等专业装备，在确保救援人员安全的前提下，组织应急救援队伍有序开展搜救被困人员工作。利用生命探测仪对可能埋压区域进行探测，使用破拆工具和挖掘设备进行清理搜救。",
      "resources": [
        { "resource_type": "生命探测仪", "quantity": 2 },
        { "resource_type": "破拆工具", "quantity": 5 },
        { "resource_type": "挖掘机", "quantity": 2 },
        { "resource_type": "吊装设备", "quantity": 1 }
      ]
    },
    {
      "step_id": 17,
      "time": "09:00",
