      "role": "医疗救护组",
      "action": "伤员转运",
      "description": "医疗救护组根据伤员伤情，将需要进一步治疗的伤员通过救护车转运至附近医院进行专业救治，转运途中持续做好生命体征监测和必要的急救处理。",
      "resources": [
        { "resource_type": "救护车", "quantity": 2 }
      ]
    },
    {
      "step_id": 19,
      "time": "09:10",
      "role": "后勤保障和善后安置组",
      "action": "安置点开放",
      "description": "属地政府在安全区域设置临时安置点，后勤保障和善后安置组开放安置场所，搭建帐篷，做好接收转移群众的各项准备工作。",
