      "time": "09:20",
      "role": "市应急局",
      "action": "资源调配",
      "description": "应急指挥部根据现场救援需要，统一调配全市应急救援资源，协调市应急局、市卫健委等部门调配救援物资、医疗药品和装备，确保救援工作顺利开展。",
      "resources": [
        { "resource_type": "物资运输车", "quantity": 3 },
        { "resource_type": "药品", "quantity": 50 }
      ]
    },
    {
      "step_id": 22,
      "time": "09:25",
      "role": "市通信管理局",
      "action": "通信保障",
      "description": "综合协调组协调市通信管理局、市国动办做好现场通信保障，调集卫星电话等通信设备，确保救援现场与指挥部之间通信畅通。",
      "resources": [
        { "resource_type": "卫星电话", "quantity": 5 },
        { "resource_type": "通信保障车", "quantity": 1 }
      ]
    },
    {
      "step_id": 23,
      "time": "09:30",
      "role": "国网厦门供电公司",
      "action": "电力保障",
      "description": "国网厦门供电公司调集发电机等设备，做好现场应急供电保障，确保救援现场照明、医疗急救等用电需求，同时对受损电力设施进行抢修。",
      "resources": [
        { "resource_type": "发电机", "quantity": 3 },
        { "resource_type": "电力抢修车", "quantity": 2 }
      ]
    },
    {
      "step_id": 24,
      "time": "09:35",
      "role": "医疗救护组",
      "action": "卫生防疫",
