        { "resource_type": "消毒设备", "quantity": 5 },
        { "resource_type": "防疫药品", "quantity": 30 }
      ]
    },
    {
      "step_id": 25,
      "time": "09:40",
      "role": "医疗救护组",
      "action": "心理援助",
      "description": "医疗救护组（市卫健委）组织心理援助专业人员对受灾群众和参与救援人员进行心理疏导和危机干预，缓解灾害带来的心理创伤。",
      "resources": [
        { "resource_type": "心理援助资料", "quantity": 50 }
      ]
    },
    {
      "step_id": 26,
      "time": "09:45",
      "role": "市生态环境局",
      "action": "环境监测",
      "description": "环境监测组对灾区及周边区域开展环境监测，重点监测饮用水源地水质、空气质量等，评估灾害对生态环境的影响，防止次生环境污染事件发生。",
      "resources": [
        { "resource_type": "环境监测设备", "quantity": 3 }
