    },
    {
      "step_id": 27,
      "time": "09:50",
      "role": "工程抢险组",
      "action": "现场处置",
      "description": "专业处置组调集各类应急装备开展灾情侦查，组织工程抢险队伍对滑坡体进行应急处置，清理滑坡堆积物，疏通道路，对不稳定边坡进行临时加固，防止次生灾害发生。",
      "resources": [
        { "resource_type": "挖掘机", "quantity": 3 },
        { "resource_type": "装载机", "quantity": 2 },
        { "resource_type": "运输车辆", "quantity": 5 }
      ]
    },
    {
      "step_id": 28,
      "time": "09:55",
      "role": "市交通局",
      "action": "设施抢修",
      "description": "工程抢险组（市交通局、市建设局等）对受灾区域受损道路、桥梁等交通设施进行抢修抢通，确保救援通道和群众出行通道畅通。",
      "resources": [
        { "resource_type": "挖掘机", "quantity": 2 },
        { "resource_type": "运输车辆", "quantity": 3 }
      ]
    },
    {
      "step_id": 29,
      "time": "10:00",
      "role": "市住房局",
      "action": "房屋鉴定",
      "description": "市住房局组织专业技术人员对灾区受损房屋进行安全鉴定，评估房屋结构安全状况，确定受损房屋能否继续使用，为群众安置和恢复重建提供依据。",
      "resources": [
        { "resource_type": "检测设备", "quantity": 3 }
      ]
    },
    {
      "step_id": 30,
      "time": "10:10",
      "role": "调查评估组",
      "action": "地灾调查",
      "description": "调查监测组（市资源规划局、市建设局、调查评估组）对地质灾害发生原因、规模、影响范围等进行全面调查，制定监测方案，明确监测方法，对灾情发展趋势进行预测及监测，形成地质灾害调查评估报告。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 3 },
        { "resource_type": "无人机", "quantity": 2 },
        { "resource_type": "卫星电话", "quantity": 1 }
      ]
    },
    {
      "step_id": 31,
      "time": "10:20",
      "role": "现场指挥部",
      "action": "处置方案",
      "description": "现场指挥部组织市资源规划局、调查评估组等专家根据地质灾害调查评估结果，制定滑坡体后续处置方案，明确工程治理、监测预警、群众安置等措施。",
      "resources": [
        { "resource_type": "地质灾害监测设备", "quantity": 2 }
      ]
